window.PhoneExperience={create(ctx){
 'use strict';
 const {data:D,gallery:G,esc,icon,btn,shell,go,save,toast,modal,appIcon}=ctx;
 const S=()=>ctx.getState(),people=D.people,wang=people[0].id,scenes=[window.MUMA_CHAT,window.MONV_CHAT,window.VIVI_CHAT].filter(Boolean);
 const Life=window.PhoneLife,group=Life?{id:Life.groupId,name:'小圣的快乐补给站',initial:'群',color:'#73a58b',alias:'粉丝群聊'}:null,chatPeople=group?[people[0],group,...people.slice(1)]:people;
 const storyFor=id=>scenes.find(s=>s.roomId===id);
 S().chatReadStories||=[];
 const albumForPerson=id=>id===wang?'xiaowang':storyFor(id)?.albumId||null;
 let tab='chats',playing=null,audio=null,activeUrl=null,mediaMenu=false,emojiMenu=false,voiceMode=false,calcValue='0',calcStored=null,calcOp=null,calcFresh=false;
 const chatViews=new Map();let nextCaret=null,forceChatEnd=null;
 const wangPortrait='assets/photos/xiaowang/xiaowang_06_windy_selfie.jpg';
 const selfPortrait=G.assets.find(a=>a.id==='fitness-02')?.path||'';
 const upload=document.createElement('input');upload.type='file';upload.accept='audio/*,.mp3,.m4a,.wav,.ogg';upload.id='chat-audio-file';upload.hidden=true;document.body.appendChild(upload);
 const person=id=>chatPeople.find(p=>p.id===id)||people[0];
 const photoList=albumId=>{const a=G.albums.find(x=>x.id===albumId);return (a?.items||[]).map(id=>G.assets.find(x=>x.id===id)).filter(Boolean);};
 const avatar=(p,self=false)=>{const path=self?selfPortrait:p.id===wang?wangPortrait:G.assets.find(a=>a.id===storyFor(p.id)?.portraitAssetId)?.path;return `<span class="wx-avatar" style="--accent:${esc(p.color||'#79958a')}">${path?`<img src="${esc(path)}" alt="${self?'小圣':esc(p.name)}" class="${self?'self-avatar':p.id===wang?'wang-avatar':p.id==='lead_monv'?'monv-avatar':'muma-avatar'}">`:esc(p.initial)}</span>`;};
 // Authored game dialogue requested by the user; never treated as verified quotations.
 const wangStory=[
  {type:'photo',assetId:'xiaowang-07',from:'other'},
  ...[
   ['other','这张拍得怎么样？'],
   ['self','风景一般。'],
   ['other','？给你一次重新组织语言的机会'],
   ['self','光顾着看你，没看风景。'],
   ['other','行，今天嘴还挺甜😌'],
   ['self','那有奖励吗？'],
   ['other','奖励你下次继续给我拍照'],
   ['self','包拍，包拎包，还包陪你吃饭。'],
   ['other','那我要吃你那份的第一口'],
   ['self','第一口给你，最后一口也给你。'],
   ['other','中间的呢？'],
   ['self','中间的得留点体力，牵你回家。'],
   ['other','少贫，外面风大，你多穿一件'],
   ['self','知道啦。你帽子扶好，别跟风跑了。'],
   ['other','放心，跑也拉着你一起'],
   ['self','那我可不松手了。'],
   ['other','本来也没让你松呀🤍']
  ].map(([from,text])=>({type:'text',from,text}))
 ].map((m,i)=>({id:'wang-story-20261024-'+i,...m}));
 const messages=id=>[...(id===group?.id?Life.seed:[]),...(id===wang?wangStory:storyFor(id)?.messages||[]),...(window.CHAT_ORIGINALS?.[id]||[]),...(S().chatMessages[id]||[])];
 const messagePhoto=m=>{const id=m.assetId||['xiaowang-01','xiaowang-02','xiaowang-03','xiaowang-04','xiaowang-05','xiaowang-06'][m.index];return G.assets.find(p=>p.id===id);};
 function messageBubble(m,p){if(m.type==='system')return `<div class="wx-chat-start">${esc(m.text)}</div>`;if(p.id===group?.id&&m.from!=='self'){const member=Life.members.find(x=>x.id===m.speaker)||Life.members[0];return `<div class="wx-message incoming wx-group-message">${avatar({...member,id:'fan_'+member.id})}<div class="wx-group-copy"><small class="wx-member-name">${esc(member.name)}</small><div class="wx-text-bubble">${esc(m.text)}</div></div></div>`;}if(m.type==='voice')return voiceBubble(m,p);const outgoing=m.from==='self';if(m.type==='photo'){const asset=messagePhoto(m),index=photoList(asset?.albumId).findIndex(p=>p.id===asset?.id);return asset?`<div class="wx-message ${outgoing?'outgoing':'incoming'}">${avatar(p,outgoing)}<button class="wx-photo-bubble" data-action="wx-photo" data-album="${esc(asset.albumId)}" data-index="${index}"><img src="${esc(asset.path)}" alt="${esc(asset.description)}"></button></div>`:'';}return `<div class="wx-message ${outgoing?'outgoing':'incoming'}" ${m.autoReply?'data-auto-reply="true"':''}>${avatar(p,outgoing)}<div class="wx-text-bubble">${esc(m.text)}</div></div>`;}

 let I=null,lifeHost=null,callState=null,callFocus=null,bannerTimer=null;
 const sound=Life?.createSound({getState:S,hidden:()=>document.hidden});
 function host(){if(!Life)return null;if(!lifeHost){lifeHost=document.createElement('div');lifeHost.className='phone-life-host';document.getElementById('phone')?.appendChild(lifeHost);}return lifeHost;}
 function hideBanner(){clearTimeout(bannerTimer);lifeHost?.querySelector('.life-banner')?.remove();}
 function drawCall(){if(!Life)return;const h=host(),old=h.querySelector('.life-call');if(!callState){old?.remove();if(old){document.getElementById('home-indicator')?.removeAttribute('inert');if(!document.querySelector('#modal-root > *'))document.getElementById('screen')?.removeAttribute('inert');callFocus?.focus?.({preventScroll:true});callFocus=null;}return;}document.getElementById('screen')?.setAttribute('inert','');document.getElementById('home-indicator')?.setAttribute('inert','');if(old?.dataset.phase===callState)return;hideBanner();old?.remove();if(!callFocus)callFocus=document.activeElement;h.insertAdjacentHTML('beforeend',`<section class="life-call" data-phase="${callState}" role="dialog" aria-modal="true" aria-label="小王的来电"><div class="life-call-top"><span>微信语音</span><span>小王的来电</span></div><div class="life-call-person">${avatar(person(wang))}<h2>小王</h2><p>${callState==='ringing'?'邀请你语音通话…':'通话中'}</p></div>${callState==='connected'?'<div class="life-call-line">“看到消息，记得回我呀。”</div>':'<div class="life-call-ripples" aria-hidden="true"><i></i><i></i><i></i></div>'}<div class="life-call-actions">${btn('life-hangup',icon('phone'),'life-call-button decline','aria-label="挂断小王的来电"')}<span>挂断</span>${callState==='ringing'?`${btn('life-answer',icon('phone'),'life-call-button accept','aria-label="接听小王的来电"')}<span>接听</span>`:''}</div><p class="life-call-footnote">剧情通话</p></section>`);h.querySelector('[data-action="life-hangup"]')?.focus({preventScroll:true});}
 function incoming(id,m,quiet=false){const active=ctx.getRoute().app==='room'&&ctx.getRoute().id===id;if(active){const scroll=document.querySelector('.wx-chat-scroll'),bottom=document.getElementById('wx-chat-bottom');if(scroll?.dataset.roomId===id&&bottom&&!m.autoReply){const follow=scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<100;bottom.insertAdjacentHTML('beforebegin',messageBubble(m,person(id)));if(follow)scroll.scrollTop=scroll.scrollHeight;}}
  if(!quiet&&!(id===group?.id&&S().phoneLife.groupMuted))sound?.message();refreshContacts();if(active||document.hidden||callState||quiet||!S().unlocked)return;hideBanner();const p=person(id),name=id===group?.id?p.name:p.name;host()?.insertAdjacentHTML('beforeend',`<aside class="life-banner" role="status"><button data-action="life-message" data-room="${esc(id)}" aria-label="打开${esc(name)}的消息">${avatar(p)}<span><small>微信 · 现在</small><strong>${esc(name)}</strong><span>${esc(id===group?.id?(Life.members.find(x=>x.id===m.speaker)?.name||'群成员')+'：'+m.text:m.text)}</span></span></button>${btn('life-dismiss','×','life-banner-close','aria-label="关闭消息提醒"')}</aside>`);bannerTimer=setTimeout(hideBanner,5500);
 }
 function refreshContacts(){const list=document.getElementById('wx-contact-list');if(list){const q=(document.getElementById('wx-contact-search')?.value||'').trim().toLowerCase();list.innerHTML=rows(chatPeople.filter(p=>(p.name+' '+(p.alias||'')).toLowerCase().includes(q)));}const tab=document.querySelector('.wx-tabs [data-tab="chats"] .wx-tab-symbol');if(tab){tab.querySelector('.wx-tab-badge')?.remove();if(unreadCount())tab.insertAdjacentHTML('beforeend','<b class="wx-tab-badge">'+unreadCount()+'</b>');}const button=document.querySelector('.app-grid [data-app="wechat"]');if(button){button.querySelector('.badge')?.remove();if(unreadCount())button.insertAdjacentHTML('beforeend','<span class="badge">'+unreadCount()+'</span>');}}
 const R=window.WangChatRuntime.create({getState:S,getRoute:ctx.getRoute,wang,save,onIncoming:(id,m)=>I?.notify(id,m),renderBubble:m=>messageBubble(m,person(wang)),refreshList:refreshContacts});
 const P=window.PersonaChatRuntime.create({getState:S,getRoute:ctx.getRoute,save,esc,onIncoming:(id,m)=>I?.notify(id,m),renderBubble:(m,id)=>messageBubble(m,person(id)),refreshList:refreshContacts});
 const unread=id=>{const scene=storyFor(id);return (id===group?.id&&!S().chatReadRooms.includes(id)&&(S().chatMessages[id]||[]).some(m=>m.from!=='self'))||(id===wang&&!S().chatReadRooms.includes(id))||(scene?.messages?.length&&!S().chatReadStories.includes(scene.storyId))||(P.supports(id)&&!S().chatReadRooms.includes(id)&&(S().chatMessages[id]||[]).some(m=>m.autoReply))?1:0;};
 function unreadCount(){return chatPeople.reduce((n,p)=>n+unread(p.id),0);}
 if(Life){S().phoneLife=Life.normalize(S().phoneLife);I=Life.create({getState:S,getRoute:ctx.getRoute,wang,save,sound,hidden:()=>document.hidden,available:()=>!document.querySelector('#modal-root > *'),onCall:phase=>{callState=phase;drawCall();},onIncoming:incoming});document.addEventListener('pointerdown',()=>sound.unlock(),{passive:true});document.addEventListener('keydown',e=>{sound.unlock();if(!callState)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();I.end('declined');}if(e.key==='Tab'){const buttons=[...host().querySelectorAll('.life-call button')];e.preventDefault();const n=buttons.indexOf(document.activeElement);buttons[(n+(e.shiftKey?buttons.length-1:1))%buttons.length]?.focus();}},true);document.addEventListener('visibilitychange',()=>{if(document.hidden){hideBanner();stopAudio();}I.visibility();});}
 function markRead(id){let changed=false;if(!S().chatReadRooms.includes(id)){S().chatReadRooms.push(id);changed=true;}const scene=storyFor(id);if(scene?.storyId&&!S().chatReadStories.includes(scene.storyId)){S().chatReadStories.push(scene.storyId);changed=true;}if(changed)save();}
 function stopAudio(){if(audio){audio.pause();audio=null;}if(activeUrl){URL.revokeObjectURL(activeUrl);activeUrl=null;}playing=null;document.querySelectorAll('.wx-voice.playing').forEach(el=>el.classList.remove('playing'));}
 const dbPromise=new Promise(resolve=>{if(!window.indexedDB){resolve(null);return;}const r=indexedDB.open('xiaosheng-phone-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('audio');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);});
 async function mediaStore(id,blob){const db=await dbPromise;if(!db)throw Error('storage');return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(blob,id);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);});}
 async function mediaLoad(id){const db=await dbPromise;if(!db)return null;return new Promise(resolve=>{const r=db.transaction('audio','readonly').objectStore('audio').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null);});}
 function nav(title,body,{className='',right='',footer='',large=false}={}){return `<section class="app-shell wx-shell ${className}"><nav class="wx-nav"><div class="wx-left">${btn('back',icon('back'),'','aria-label="返回桌面"')}</div><h1>${esc(title)}</h1><div class="wx-right">${right}</div></nav><div class="app-scroll wx-scroll ${large?'wx-large':''}">${body}</div>${footer}</section>`;}
 function tabs(){return `<nav class="wx-tabs">${[['chats','bubble','微信'],['contacts','user','通讯录'],['discover','compass','发现'],['me','user','我']].map(([id,i,label])=>`<button data-action="wx-tab" data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}"><span class="wx-tab-symbol">${icon(i)}${id==='chats'&&unreadCount()?`<b class="wx-tab-badge">${unreadCount()}</b>`:''}</span><span>${label}</span></button>`).join('')}</nav>`;}
 function rows(list=chatPeople){if(!list.length)return '<p class="wx-search-empty" role="status">没有找到联系人，试试换个名字</p>';return list.map(p=>{const ms=messages(p.id),last=ms.at(-1);const preview=last?(last.type==='voice'?'[语音]':last.type==='photo'?'[图片]':last.text):p.id===wang?'[图片]':'暂无消息';return `<button class="wx-contact ${p.id===wang?'pinned':''}" data-action="room" data-id="${p.id}"><span class="wx-avatar-wrap">${avatar(p)}${unread(p.id)?'<b class="wx-unread">1</b>':''}</span><span class="wx-contact-copy"><strong>${esc(p.name)}${p.id===group?.id?'<span class="wx-group-count">(4)</span>':''}</strong><small>${esc(p.id===group?.id&&last?.speaker?(Life.members.find(x=>x.id===last.speaker)?.name||'群成员')+'：'+preview:preview)}</small></span><span class="wx-contact-end">${last?.time?esc(last.time):''}</span></button>`;}).join('');}
 function wechat(){
  let body='',right=btn('wx-options',icon('plus'),'','aria-label="微信菜单"');
  if(tab==='chats')body=`<label class="wx-search">${icon('search')}<input id="wx-contact-search" type="search" placeholder="搜索" aria-label="搜索微信联系人"></label><div id="wx-contact-list">${rows()}</div>`;
  if(tab==='contacts')body=`<div class="wx-contact-tools">${btn('wx-new',`<span class="wx-tool-icon">${icon('plus')}</span>新的朋友`,'wx-setting-row')}${btn('favorites',`<span class="wx-tool-icon gold">${icon('star')}</span>收藏`,'wx-setting-row')}</div><div class="wx-section-label">联系人</div>${people.map(p=>`<button class="wx-person-row" data-action="room" data-id="${p.id}">${avatar(p)}<span>${esc(p.name)}</span></button>`).join('')}`;
  if(tab==='discover')body=`<div class="wx-group">${btn('wx-moments',`<span class="wx-tool-icon blue">${icon('compass')}</span><span>朋友圈</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row')}</div>`;
  if(tab==='me')body=`<div class="wx-profile">${avatar({id:'self'},true)}<div><h2>小圣</h2><p>照片、收藏与生活</p></div></div><div class="wx-group">${btn('favorites',`<span class="wx-tool-icon gold">${icon('star')}</span><span>收藏</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row')}${btn('wx-moments',`<span class="wx-tool-icon blue">${icon('grid')}</span><span>朋友圈</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row')}${btn('app',`<span class="wx-tool-icon">${icon('folder')}</span><span>文件</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row','data-app="files"')}</div><div class="wx-group">${btn('app',`<span class="wx-tool-icon">${icon('sun')}</span><span>设置</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row','data-app="settings"')}</div><div class="wx-group"><button type="button" class="wx-setting-row" data-dev-support><span class="wx-tool-icon gold" aria-hidden="true">🌶️</span><span class="wx-support-copy">支持开发者<small>微信 ¥0.99 · 自愿支持</small></span><span class="wx-row-end">${icon('chevron')}</span></button></div>`;
  return nav(tab==='chats'?'微信':tab==='contacts'?'通讯录':tab==='discover'?'发现':'我',body,{right,footer:tabs(),className:tab==='me'||tab==='discover'?'wx-muted':''});
 }
 function voiceBubble(m,p){const listened=S().playedVoiceIds.includes(m.id);return `<div class="wx-message ${m.from==='self'?'outgoing':'incoming'}"><span>${avatar(p,m.from==='self')}</span><div class="wx-voice-wrap"><button class="wx-voice ${playing===m.id?'playing':''}" style="width:${Math.min(215,92+(m.duration||1)*4)}px" data-action="wx-voice" data-id="${esc(m.id)}" data-room="${p.id}" aria-label="播放语音 ${Math.ceil(m.duration||0)}秒"><span class="wx-voice-waves"><i></i><i></i><i></i></span><b>${Math.ceil(m.duration||0)}″</b></button>${!listened?'<i class="wx-voice-unheard" aria-label="未听语音"></i>':''}</div></div>`;}
 function room(){const p=person(ctx.getRoute().id);markRead(p.id);const ms=messages(p.id);
  return `<section class="app-shell wx-shell wx-room"><nav class="wx-nav"><div class="wx-left">${btn('back',icon('back'),'','aria-label="返回微信"')}</div><h1>${esc(p.name)}${p.id===group?.id?' (4)':''}</h1><div class="wx-right">${btn('wx-room-info',icon('dots'),'','aria-label="聊天详情"')}</div></nav><div class="app-scroll wx-chat-scroll" data-room-id="${esc(p.id)}"><div class="wx-chat-start">${esc(storyFor(p.id)?p.alias||p.name:p.name)}</div>${ms.length?'':`<div class="wx-no-messages">${avatar(p)}<span>${esc(p.name)}</span></div>`}${ms.map(m=>messageBubble(m,p)).join('')}${p.id===wang?R.typingMarkup(avatar(p)):P.supports(p.id)?P.typingMarkup(p.id,avatar(p),p.name):''}<div id="wx-chat-bottom"></div></div><form class="wx-composer" data-form="wx-message">${p.id===group?.id?'':`<button type="button" data-action="wx-mic" aria-label="语音消息">${icon(voiceMode?'edit':'volume')}</button>`}${voiceMode?btn('wx-import','导入原声','wx-hold-voice','type="button"'):`<textarea id="wx-message-input" aria-label="消息" rows="1" maxlength="1000">${esc(S().chatDrafts[p.id]||'')}</textarea>`}<button type="button" data-action="wx-emoji" aria-label="表情"><span class="wx-smile">☺</span></button>${p.id===group?.id?'':`<button type="button" data-action="wx-attach" aria-label="添加">${icon('plus')}</button>`}${!voiceMode&&(S().chatDrafts[p.id]||'').trim()?'<button class="wx-send" type="submit">发送</button>':''}</form>${emojiMenu?`<div class="wx-extra-panel wx-emojis">${['🙂','❤️','😂','🌊','🌅','✨','🥺','😎','👍','👀','🤍','🌙'].map(x=>btn('wx-insert-emoji',x,'',`data-emoji="${x}"`)).join('')}</div>`:''}${mediaMenu?`<div class="wx-extra-panel"><button data-action="wx-pick-photo">${icon('grid')}<span>照片</span></button><button data-action="wx-import">${icon('volume')}<span>导入原声</span></button><button data-action="favorites">${icon('star')}<span>收藏</span></button></div>`:''}</section>`;
 }
 function chatMenu(){modal('phone-actions',{title:'微信',items:[{action:'wx-new',label:'新建聊天',glyph:'bubble'},{action:'favorites',label:'收藏',glyph:'star'}]});}
 async function toggleVoice(id,roomId){if(playing===id){stopAudio();return;}stopAudio();const m=messages(roomId).find(x=>x.id===id);if(!m)return;let url=m.src;if(!url){const blob=await mediaLoad(m.blobKey);if(!blob){toast('原声文件不可用，请重新导入');return;}url=URL.createObjectURL(blob);activeUrl=url;}const next=new Audio(url);audio=next;playing=id;next.onended=()=>{if(audio===next){playing=null;audio=null;document.querySelector(`[data-action="wx-voice"][data-id="${id}"]`)?.classList.remove('playing');}if(!m.src)URL.revokeObjectURL(url);};next.onerror=()=>{stopAudio();toast('这段音频暂时无法播放');if(!m.src)URL.revokeObjectURL(url);};try{await next.play();if(audio!==next)return;if(!S().playedVoiceIds.includes(id)){S().playedVoiceIds.push(id);save();}const b=document.querySelector(`[data-action="wx-voice"][data-id="${id}"]`);b?.classList.add('playing');b?.parentElement.querySelector('.wx-voice-unheard')?.remove();}catch{stopAudio();toast('点一下语音条重新播放');}}
 upload.addEventListener('change',async()=>{const file=upload.files?.[0],roomId=ctx.getRoute().id;upload.value='';if(!file||!roomId)return;if(file.size>30*1024*1024){toast('请选择小于30MB的音频');return;}const url=URL.createObjectURL(file),probe=new Audio();probe.preload='metadata';probe.src=url;probe.onloadedmetadata=async()=>{const duration=probe.duration;URL.revokeObjectURL(url);if(!Number.isFinite(duration)||duration<=0){toast('无法读取音频时长');return;}const id='voice_'+Date.now();try{await mediaStore(id,file);S().chatMessages[roomId]||=[];S().chatMessages[roomId].push({id,type:'voice',blobKey:id,duration,from:'clip',name:file.name,time:new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())});save();mediaMenu=false;voiceMode=false;ctx.render();requestAnimationFrame(()=>document.querySelector('#wx-chat-bottom')?.scrollIntoView({block:'end'}));}catch{toast('无法保存音频，请检查浏览器存储权限');}};probe.onerror=()=>{URL.revokeObjectURL(url);toast('无法读取这个音频格式');};});
 function moments(){return nav('朋友圈',`<div class="wx-moments-cover"><img src="${esc(photoList('xiaowang').find(p=>p.id==='xiaowang-05')?.path||'')}" alt="雪山"><h2>小圣</h2>${avatar({id:'self'},true)}</div><p class="wx-no-messages">朋友们最近没有更新动态</p>`);}
 function profileSheet(){const p=person(ctx.getRoute().id);if(p.id===group?.id){modal('phone-actions',{title:group.name+'（4）',note:'小圣、阿柚、小米饭、晚风\n本机情景群聊 · 群成员为游戏角色。',items:[{action:'fans-mute',label:'消息提示音 · '+(S().phoneLife.groupMuted?'已静音':'已开启'),glyph:'volume'}]});return;}modal('phone-actions',{title:p.name,avatar:p.id,items:[{action:'wx-import',label:'导入原声',glyph:'volume'},...(p.id===wang?[{action:'wx-replies-toggle',label:'自动回复 · '+(R.enabled()?'已开启':'已暂停')+'（'+R.mode()+'）',glyph:'bubble'}]:[]),...(P.supports(p.id)?[{action:'persona-toggle',label:'自动回复 · '+(P.enabled(p.id)?'已开启':'已暂停')+'（情景对话）',glyph:'bubble'},{action:'persona-memory-toggle',label:'偏好记忆 · '+(P.memoryEnabled(p.id)?'已开启':'已关闭'),glyph:'edit'},{action:'persona-memory-clear',label:'清除本角色记忆',glyph:'edit'},{action:'persona-chat-clear',label:'清除动态聊天记录',glyph:'bubble'}]:[]),{action:'favorites',label:'收藏',glyph:'star'}],note:P.supports(p.id)?'粉丝同人创作 · 角色对话为虚构演绎，非真实私人聊天。\n此刻：'+P.mood(p.id)+'。只在本机记住你主动告诉此角色的昵称、饮食、想去的地方与小约定。':undefined});}
 function safari(){return shell('Safari',`<div class="browser-bar safari-address" data-action="search" role="button" tabindex="0">${icon('search')}搜索</div><div class="padded safari-start"><h2>个人收藏</h2><div class="safari-bookmarks">${[['photos','照片','grid'],['wechat','微信','bubble'],['notes','备忘录','edit'],['favorites','收藏','star']].map(([app,name,i])=>btn('app',`<span>${icon(i)}</span><b>${name}</b>`,'',`data-app="${app}"`)).join('')}</div><h2>最近浏览</h2><div class="safari-history">${S().opened.filter(x=>!['home','safari','douyin'].includes(x)).slice(-6).reverse().map(app=>btn('app',`${icon('clock')}<span>${({wechat:'微信',room:'聊天',photos:'照片',notes:'备忘录',settings:'设置',album:'相册',calculator:'计算器',files:'文件',favorites:'收藏'})[app]||'手机'}</span>${icon('chevron')}`,'list-row',`data-app="${app==='room'?'wechat':app==='album'?'photos':app}"`)).join('')}</div></div>`);}
 function calculator(){return shell('计算器',`<div class="calc-screen"><div class="calc-display" aria-live="polite">${esc(calcValue)}</div><div class="calc-grid">${['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','='].map(k=>btn('calc-key',k,'calc-key '+('÷×−+='.includes(k)?'operator':['AC','±','%'].includes(k)?'function-key':k==='0'?'zero':''),`data-key="${k}"`)).join('')}</div></div>`,{className:'calculator-app'});}
 function calc(k){if(/^\d$/.test(k)){calcValue=calcFresh||calcValue==='0'?k:(calcValue.length<12?calcValue+k:calcValue);calcFresh=false;}else if(k==='.'){if(calcFresh){calcValue='0';calcFresh=false;}if(!calcValue.includes('.'))calcValue+='.';}else if(k==='AC'){calcValue='0';calcStored=null;calcOp=null;calcFresh=false;}else if(k==='±')calcValue=String(-Number(calcValue));else if(k==='%')calcValue=String(Number(calcValue)/100);else{if(k==='='&&['520','0520'].includes(calcValue)&&calcStored===null){egg('calculator-0520','0520，记住了。');go('album',{id:'xiaowang'});return;}const value=Number(calcValue);if(calcStored!==null&&calcOp&&!calcFresh){const n=calcOp==='+'?calcStored+value:calcOp==='−'?calcStored-value:calcOp==='×'?calcStored*value:value===0?NaN:calcStored/value;calcValue=Number.isFinite(n)?String(Number(n.toPrecision(10))):'错误';}calcStored=k==='='?null:Number(calcValue);calcOp=k==='='?null:k;calcFresh=true;}const display=document.querySelector('.calc-display');if(display)display.textContent=calcValue;}
 function egg(id,text){if(!S().discovered.includes(id)){S().discovered.push(id);save();}toast(text);}
 function beforeRender(){const scroll=document.querySelector('.wx-chat-scroll');if(!scroll)return;const input=document.getElementById('wx-message-input'),id=scroll.dataset.roomId,old=chatViews.get(id);chatViews.set(id,{top:scroll.scrollTop,atEnd:scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<80,start:input?.selectionStart??old?.start,end:input?.selectionEnd??old?.end});}
 function afterRender(){I?.sync();drawCall();const input=sizeComposer(),scroll=document.querySelector('.wx-chat-scroll');if(!scroll)return;const id=scroll.dataset.roomId,view=chatViews.get(id),caret=nextCaret?.id===id?nextCaret:view;scroll.scrollTop=forceChatEnd===id||!view||view.atEnd?scroll.scrollHeight:view.top;if(input&&typeof caret?.start==='number')input.setSelectionRange(Math.min(input.value.length,caret.start),Math.min(input.value.length,caret.end??caret.start));if(nextCaret?.id===id)nextCaret=null;if(forceChatEnd===id)forceChatEnd=null;}
 function sizeComposer(el=document.getElementById('wx-message-input')){if(el){el.style.height='auto';el.style.height=Math.min(85,el.scrollHeight)+'px';}return el;}
 function send(){const id=ctx.getRoute().id,text=(S().chatDrafts[id]||'').trim();if(!text)return;S().chatMessages[id]||=[];const message={id:'text_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),type:'text',text,from:'self',time:new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())};S().chatMessages[id].push(message);S().chatDrafts[id]='';emojiMenu=false;if(id===wang)R.enqueue(message);if(P.supports(id))P.enqueue(id,message);if(id===group?.id)I.enqueueGroup(message);forceChatEnd=id;save();ctx.render();sizeComposer()?.focus({preventScroll:true});}

 function action(a,t){switch(a){case'life-answer':I?.answer();return true;case'life-hangup':I?.end('declined');return true;case'life-message':hideBanner();go('room',{id:t.dataset.room});return true;case'life-dismiss':hideBanner();return true;case'fans-mute':I.toggleGroupMute();ctx.closeModal();toast(S().phoneLife.groupMuted?'群消息已静音':'群消息提示音已开启');return true;case'life-sound':S().settings.sound=S().settings.sound===false;save();sound.stop();if(S().settings.sound){sound.unlock();sound.message();}ctx.render();return true;case'persona-toggle':{const id=ctx.getRoute().id;if(!P.supports(id))return true;const on=P.toggle(id);ctx.closeModal();ctx.render();toast(on?'自动回复已开启':'自动回复已暂停');return true;}case'persona-memory-toggle':{const id=ctx.getRoute().id;if(!P.supports(id))return true;const on=P.toggleMemory(id);ctx.closeModal();toast(on?'偏好记忆已开启':'偏好已清除，记忆已关闭');return true;}case'persona-memory-clear':{const id=ctx.getRoute().id;if(!P.supports(id))return true;P.clearMemory(id);ctx.closeModal();toast('本角色记忆已清除，聊天记录保留');return true;}case'persona-chat-clear':{const id=ctx.getRoute().id;if(!P.supports(id))return true;ctx.closeModal();modal('phone-actions',{title:'清除此角色的动态聊天？',note:'将删除本机的输入、自动回复、草稿及偏好记忆。原有故事和照片保留。',items:[{action:'persona-chat-confirm',label:'确认清除动态聊天',glyph:'edit'},{action:'modal-close',label:'保留聊天',glyph:'bubble'}]});return true;}case'persona-chat-confirm':{const id=ctx.getRoute().id;if(!P.supports(id))return true;P.clearChat(id);chatViews.delete(id);ctx.closeModal();ctx.render();toast('动态聊天与记忆已清除');return true;}case'wx-replies-toggle':{const on=R.toggle();ctx.closeModal();ctx.render();toast(on?'小王自动回复已开启':'小王自动回复已暂停');return true;}case'wx-tab':tab=t.dataset.tab;mediaMenu=false;emojiMenu=false;ctx.render();return true;case'wx-new':tab='contacts';ctx.closeModal();go('wechat');return true;case'wx-options':chatMenu();return true;case'wx-room-info':profileSheet();return true;case'wx-attach':mediaMenu=!mediaMenu;emojiMenu=false;ctx.render();return true;case'wx-mic':voiceMode=!voiceMode;mediaMenu=false;emojiMenu=false;ctx.render();return true;case'wx-emoji':emojiMenu=!emojiMenu;mediaMenu=false;ctx.render();return true;case'wx-insert-emoji':{const id=ctx.getRoute().id,text=S().chatDrafts[id]||'',input=document.getElementById('wx-message-input'),start=input?.selectionStart??text.length,end=input?.selectionEnd??start,emoji=t.dataset.emoji||'',draft=text.slice(0,start)+emoji+text.slice(end);if(draft.length>1000){toast('最多输入1000个字符');return true;}S().chatDrafts[id]=draft;nextCaret={id,start:start+emoji.length,end:start+emoji.length};voiceMode=false;save();ctx.render();return true;}case'wx-import':ctx.closeModal();upload.click();return true;case'wx-photo':{const albumId=t.dataset.album||'xiaowang',index=Number(t.dataset.index),asset=photoList(albumId)[index];if(asset)modal('photo',{albumId,index,assetId:asset.id});return true;}case'wx-feed-photo':modal('photo',{albumId:t.dataset.album,index:Number(t.dataset.index)});return true;case'wx-album':{const r=ctx.getRoute();ctx.closeModal();go('album',{id:albumForPerson(r.id)||'xiaowang',...(r.app==='room'?{returnRoom:r.id}:{})});return true;}case'wx-self-album':go('album',{id:'fitness'});return true;case'wx-moments':go('moments');return true;case'wx-pick-photo':{const albumId=albumForPerson(ctx.getRoute().id)||'xiaowang';modal('phone-actions',{title:'照片',albumId,photos:photoList(albumId).map((p,i)=>({path:p.path,index:i}))});return true;}case'wx-send-photo':{const id=ctx.getRoute().id;S().chatMessages[id]||=[];S().chatMessages[id].push({id:'photo_'+Date.now(),type:'photo',assetId:photoList(t.dataset.album||albumForPerson(id)||'xiaowang')[Number(t.dataset.index)]?.id,from:'self'});forceChatEnd=id;save();ctx.closeModal();mediaMenu=false;ctx.render();return true;}case'wx-voice':toggleVoice(t.dataset.id,t.dataset.room);return true;case'calc-key':calc(t.dataset.key);return true;case'wx-egg':egg('settings-profile','有些照片，值得再看一遍。');go('album',{id:'xiaowang'});return true;default:return false;}}
 function input(el){if(el.id==='wx-contact-search'){document.getElementById('wx-contact-list').innerHTML=rows(chatPeople.filter(p=>(p.name+' '+(p.alias||'')).toLowerCase().includes(el.value.trim().toLowerCase())));return true;}if(el.id==='wx-message-input'){const id=ctx.getRoute().id;S().chatDrafts[id]=el.value;save();const form=el.closest('form');let send=form.querySelector('.wx-send');if(el.value.trim()&&!send){send=document.createElement('button');send.type='submit';send.className='wx-send';send.textContent='发送';form.appendChild(send);}else if(!el.value.trim()&&send)send.remove();sizeComposer(el);return true;}return false;}
 function renderActions(data){return `<h2>${esc(data.title)}</h2>${data.note?`<p class="persona-notice">${esc(data.note)}</p>`:''}${data.photos?`<div class="wx-pick-grid">${data.photos.map(p=>btn('wx-send-photo',`<img src="${esc(p.path)}" alt="照片">`,'',`data-index="${p.index}" data-album="${esc(data.albumId||'xiaowang')}"`)).join('')}</div>`:`<div class="list-group">${(data.items||[]).map(x=>btn(x.action,icon(x.glyph)+`<span class="row-label">${esc(x.label)}</span>`+icon('chevron'),'list-row')).join('')}</div>`}`;}
 return {wechat,room,moments,safari,calculator,action,input,send,stopAudio,unreadCount,markRead,renderActions,avatar,egg,onNavigate(){hideBanner();stopAudio();mediaMenu=false;emojiMenu=false;voiceMode=false;},beforeRender,afterRender};
}};
